"use strict";

// ===== 装飾（トップページ専用）：背景イラストの散らし＋セクションのフェードイン =====

// 背景に散らすイラスト一覧。あとから追加したいときは、この配列に1行足すだけ。
// （GitHubへの一括pushが画像ファイルに未対応のため、サイト表示用はデータURIで埋め込み。
//   元のPNGは img/bg/ フォルダにも置いてある）
const BG_ILLUSTS = [
  "data:image/png;base64,",
  "data:image/png;base64,",
  "data:image/png;base64,",
  "data:image/png;base64,",
  "data:image/png;base64,",
];

// 散らし配置の固定スロット（top/left はラッパーに対する %、size は px、rot は deg）
const BG_SCATTER_SLOTS = [
  { top: "1%", left: "84%", size: 104, rot: 10 },
  { top: "6%", left: "4%", size: 84, rot: -8 },
  { top: "13%", left: "66%", size: 118, rot: 6 },
  { top: "20%", left: "90%", size: 76, rot: -12 },
  { top: "27%", left: "10%", size: 96, rot: 12 },
  { top: "34%", left: "80%", size: 88, rot: -6 },
  { top: "41%", left: "2%", size: 110, rot: 8 },
  { top: "48%", left: "70%", size: 78, rot: -10 },
  { top: "55%", left: "88%", size: 100, rot: 14 },
  { top: "62%", left: "8%", size: 82, rot: -14 },
  { top: "69%", left: "62%", size: 108, rot: 5 },
  { top: "76%", left: "92%", size: 72, rot: -7 },
  { top: "83%", left: "14%", size: 98, rot: 11 },
  { top: "90%", left: "76%", size: 86, rot: -11 },
  { top: "96%", left: "36%", size: 92, rot: 7 },
];

// 背景レイヤー（.scatter-bg）に、配列のイラストを順番に使い回して配置する
function renderScatterBg() {
  const layer = document.querySelector(".scatter-bg");
  if (!layer || BG_ILLUSTS.length === 0) return;
  BG_SCATTER_SLOTS.forEach((slot, i) => {
    const img = document.createElement("img");
    img.src = BG_ILLUSTS[i % BG_ILLUSTS.length];
    img.alt = "";
    img.className = "scatter-item";
    img.style.top = slot.top;
    img.style.left = slot.left;
    img.style.width = `${slot.size}px`;
    img.style.transform = `rotate(${slot.rot}deg)`;
    layer.appendChild(img);
  });
}
renderScatterBg();

// ===== セクションごとのフェードイン =====
// JSが有効なときだけ初期状態（透明）を付け、画面に入ったら1回だけ再生する。
// JS無効・失敗時は最初から全部見える。「動きを減らす」設定では再生しない
const reduceMotion = window.matchMedia(
  "(prefers-reduced-motion: reduce)",
).matches;
if (!reduceMotion && "IntersectionObserver" in window) {
  const targets = document.querySelectorAll("[data-fade]");
  targets.forEach((el) => el.classList.add("fade-init"));
  const io = new IntersectionObserver(
    (entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          entry.target.classList.add("fade-play");
          io.unobserve(entry.target);
        }
      });
    },
    { rootMargin: "0px 0px 120px 0px", threshold: 0.05 },
  );
  targets.forEach((el) => io.observe(el));
}
